mapper.select:
select id, member_id, topic_id, values_json, source_session_id, source_version, create_time, update_time
from theme_character
where member_id = #{memberId} and topic_id = #{topicId}

mapper.update:
update theme_character
set values_json = #{valuesJson},
    source_session_id = #{sourceSessionId},
    source_version = #{sourceVersion},
    update_time = #{updateTime}
where member_id = #{memberId} and topic_id = #{topicId}
  and (source_session_id < #{sourceSessionId}
       or (source_session_id = #{sourceSessionId} and source_version < #{sourceVersion}))
